int temperature = 23;

if (temperature >= 30)
{
    Console.WriteLine("Hot");
}
else if (temperature >= 20)
{
    Console.WriteLine("Pleasant");
}
else
{
    Console.WriteLine("Cold");
}

string advice = temperature > 25 ? "Bring water" : "Bring a jacket";
Console.WriteLine(advice);

string day = "Saturday";

switch (day)
{
    case "Saturday":
    case "Sunday":
        Console.WriteLine("Weekend");
        break;
    case "Friday":
        Console.WriteLine("Almost weekend");
        break;
    default:
        Console.WriteLine("Weekday");
        break;
}

int httpStatus = 404;

string message = httpStatus switch
{
    200 => "OK",
    301 or 302 => "Redirect",
    404 => "Not found",
    >= 500 => "Server error",
    _ => "Something else",
};
Console.WriteLine(message);

Console.WriteLine(Grade(91));
Console.WriteLine(Grade(64));

string Grade(int score) => score switch
{
    >= 90 => "A",
    >= 75 => "B",
    >= 60 => "C",
    _ => "F",
};

for (int i = 1; i <= 3; i++)
{
    Console.WriteLine($"for: {i}");
}

string[] fruits = ["apple", "kiwi", "plum"];
foreach (string fruit in fruits)
{
    Console.WriteLine($"foreach: {fruit}");
}

int countdown = 2;
while (countdown > 0)
{
    Console.WriteLine($"while: {countdown}");
    countdown--;
}

int attempts = 0;
do
{
    attempts++;
    Console.WriteLine($"do: attempt {attempts}");
} while (attempts < 1);

for (int n = 1; n <= 10; n++)
{
    if (n % 2 == 0) continue;   // skip even numbers
    if (n > 7) break;           // stop entirely after 7
    Console.WriteLine(n);
}
Console.WriteLine("done");

for (int row = 1; row <= 3; row++)
{
    string line = "";
    for (int col = 1; col <= 3; col++)
    {
        line += $"{row * col,3}";
    }
    Console.WriteLine(line);
}

